SHOW PRIMARY KEYS;

SHOW TERSE PRIMARY KEYS IN ACCOUNT;

SHOW PRIMARY KEYS IN DATABASE my_db;

SHOW PRIMARY KEYS IN SCHEMA my_db.my_schema;

SHOW PRIMARY KEYS IN TABLE my_table;

SHOW PRIMARY KEYS IN my_db.my_schema.my_table;

SHOW CATALOG INTEGRATIONS;

SHOW CATALOG INTEGRATIONS LIKE 'my%';

SHOW NOTEBOOKS;

SHOW NOTEBOOKS LIKE 'my%' IN SCHEMA my_db.my_schema STARTS WITH 'my' LIMIT 10 FROM 'my_nb';

SHOW CONNECTIONS;

SHOW CONNECTIONS LIKE 'my%';

SHOW MANAGED ACCOUNTS;

SHOW MANAGED ACCOUNTS LIKE 'my%';

SELECT connections FROM connection_stats AS connections;
